        ranges.append(f'{col}{r}')
for r in range(35,41):
    for col in ['H','I','J','K','L']:
        ranges.append(f'{col}{r}')
for r in range(42,48):
    for col in ['H','I','J','K','L']:
        ranges.append(f'{col}{r}')
for col in ['H','I','J','K','L']:
    ranges.append(f'{col}50')

