if non_formula:
    print('Examples:', non_formula[:10])

# Spot check some formulas
spot=['H12','I12','H19','H26','H35','H42','H46','H50','L50']
for addr in spot:
    print(addr, ws[addr].value)

# Ensure stats labels mapping intact
for r in range(42,48):
    print('E'+str(r), ws['E'+str(r)].value, '->', ws['H'+str(r)].value)
"

